import{_ as a,o as t,c as l,a4 as o}from"./chunks/framework.DzJZdBQK.js";const _=JSON.parse('{"title":"写作课作业-113","description":"","frontmatter":{"date":"2021-03-07T15:33:09","title":"写作课作业-113","categories":["写作","作业","区块链小白书"],"tags":["写作","作业","区块链小白书"]},"headers":[{"level":2,"title":"2W1H","slug":"_2w1h","link":"#_2w1h","children":[{"level":3,"title":"What","slug":"what","link":"#what","children":[]},{"level":3,"title":"Why","slug":"why","link":"#why","children":[]},{"level":3,"title":"How","slug":"how","link":"#how","children":[]}]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/113.md","filePath":"posts/homework/113.md"}'),r={name:"posts/homework/113.md"};function h(i,e,n,p,s,c){return t(),l("div",null,[...e[0]||(e[0]=[o('<blockquote><p>《区块链小白书》之《比特币 9.区块链有没有被篡改的风险》</p></blockquote><h2 id="_2w1h" tabindex="-1">2W1H <a class="header-anchor" href="#_2w1h" aria-label="Permalink to &quot;2W1H&quot;">​</a></h2><h3 id="what" tabindex="-1">What <a class="header-anchor" href="#what" aria-label="Permalink to &quot;What&quot;">​</a></h3><p>区块链通过分布式管理本身，是无法做到“无法篡改”的——顶多能做到“很难篡改”。</p><h3 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h3><p>通过“51攻击”的方式，可以达到篡改区块链，而这个问题不能通过技术解决。比特币引入利益驱动（博弈原理），使得“贡献”远比“攻击”更有利可图。</p><blockquote><p>奖励机制也可能会鼓励节点保持诚实。如果一个贪婪的攻击者能够网罗比所有诚实节点都更多的 CPU 算力，他必须做出一个选择：是用这些算力通过把自己花出去的钱偷回来去欺骗别人呢？还是用这些算力去生成新的硬币？他应该能够发现按照规则行事是更划算的，当前规则使得他能够获得比所有其他人加起来都更多的硬币，这显然比暗中摧毁系统并使自己的财富化为虚无更划算。</p></blockquote><h3 id="how" tabindex="-1">How <a class="header-anchor" href="#how" aria-label="Permalink to &quot;How&quot;">​</a></h3><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>技术通过跨界才能真正解决实际的问题，产生价值。</p><p>完整读<a href="http://lixiaolai.com/#/bitcoin-whitepaper-cn-en-translation/Bitcoin-Whitepaper-EN-CN.html" target="_blank" rel="noreferrer">《比特币白皮书》</a></p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',18)])])}const u=a(r,[["render",h]]);export{_ as __pageData,u as default};
